-- ===========================================================================
-- pettycash_test :: reports, xero and billing   (GENERATED by generators/gen.py)
--
--   reads   pettycashv2      at alembic HEAD (whatever migrations/versions ends in)
--   writes  pettycash_test   built by 01_schema_rebased.sql; needs 02 COMMITTED
--
--     psql "$URL" -v ON_ERROR_STOP=1 -f docs/schema/03_data_reports_rebased.sql
--
-- Ends in ROLLBACK. rehearse.py flips it to COMMIT with --commit.
--
-- The expense receipts load LAST, after the checks on the copied tables:
-- shop_expense.files -> attachment + report_expense_attachment (01 header,
-- ERA 3 item 11; "EXPENSE RECEIPTS" below). Until 2026-09-28 that was a
-- separate Python step, 04_data_attachments.py.
--
-- THE CHECKS
--   R1  row parity, with the EXPECTED skip per guarded table
--   R3  every enum mapping landed with exactly the mapped counts
--   R5  no key was lost
--   R6  money did not move (double precision -> numeric)
--   R7  the sales breakdown is the same number: per report, the report_sale
--       rows sum to what the legacy columns said
--   R8  the cash count view reproduces report.actual_cash_total, NULL for NULL
--   R9  every receipt key of every carried expense is linked, and every key
--       is a whole key (no fragment of a split)
-- ===========================================================================

BEGIN;
SET LOCAL TIME ZONE 'Asia/Hong_Kong';

-- Nothing below tolerates a partial previous run.
TRUNCATE TABLE
  pettycash_test.xero_report_sync,
  pettycash_test.xero_bill_sync_payload,
  pettycash_test.xero_bill_sync_line,
  pettycash_test.xero_bill_response_line,
  pettycash_test.xero_bill_sync,
  pettycash_test.xero_bank_transfer,
  pettycash_test.xero_bank_transaction,
  pettycash_test.user_stripe_customer,
